//
//  SubscriptionStore.swift
//  CSQTT iOS
//
//  Owns the subscriptions, refreshes them, and turns their links into ordinary
//  ServerProfile values.
//
//  🚨 ONE SUBSCRIPTION = ONE DEVICE. A provider binds an account to a device
//  identity (WRAP-A's GETCONF peer, csqtt's password binding). Five servers of
//  one subscription with five freshly minted IDs would read as five devices and
//  can trip the provider's device limit. The identity is therefore stored ONCE
//  on the subscription and stamped onto every profile it produces — and it is
//  deliberately NOT regenerated by a refresh. `resetDevice` is the explicit,
//  user-visible way to become a new device.
//

import Foundation

@MainActor
final class SubscriptionStore: ObservableObject {
    static let shared = SubscriptionStore()

    @Published private(set) var subscriptions: [Subscription] = []
    @Published private(set) var refreshing: Set<UUID> = []

    private let d = UserDefaults.standard
    private let key = "subscriptions_v1"

    private init() {
        load()
        ensureDeviceIdentities()
    }

    func subscription(_ id: UUID) -> Subscription? {
        subscriptions.first { $0.id == id }
    }

    func serversCount(_ id: UUID) -> Int {
        ServerStore.shared.servers(for: id).count
    }

    // MARK: - Add / remove

    func add(url: String,
             name: String? = nil,
             numConnections: Int? = nil) async throws -> Subscription {
        let trimmed = url.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let parsedURL = URL(string: trimmed), let scheme = parsedURL.scheme?.lowercased()
        else { throw SubscriptionError.badURL }
        guard scheme == "https" || (scheme == "http" && isLocal(parsedURL))
        else { throw SubscriptionError.insecureURL }

        let parsed = try await fetchServers(from: parsedURL)
        guard !parsed.isEmpty else { throw SubscriptionError.empty }

        var sub = Subscription(name: "", url: trimmed)
        sub.name = (name?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
                    ? name! : (parsedURL.host ?? "Subscription"))
        // The "conn" the sheet asked for, clamped the way connect() clamps the
        // anonymous path — a subscription must not promise a number the tunnel
        // will refuse.
        sub.numConnections = numConnections.map { min(max($0, 1), TunnelConfig.anonConnCap) }
        // One identity for the whole subscription. If a link already carries a
        // provider-bound device id, adopt that one so the provider recognises
        // the device it minted; otherwise mint one.
        let seed = profiles(from: parsed, subscription: sub.id, identity: nil,
                            connections: sub.numConnections)
        sub.deviceID = identity(in: seed) ?? UUID().uuidString
        sub.lastUpdated = Date()

        let final = profiles(from: parsed, subscription: sub.id, identity: sub.deviceID,
                             connections: sub.numConnections)
        guard ServerStore.shared.replaceSubscriptionServers(sub.id, with: final) || !final.isEmpty else {
            throw SubscriptionError.empty
        }
        subscriptions.append(sub)
        save()
        SharedLogger.shared.log("[AppDebug] subscription added: \(sub.hostLabel), "
            + "\(final.count) server(s), one device \(sub.shortIdentity)")
        return sub
    }

    func remove(_ id: UUID) {
        ServerStore.shared.removeSubscriptionServers(id)
        subscriptions.removeAll { $0.id == id }
        save()
    }

    // MARK: - Refresh

    func refresh(_ id: UUID) async {
        guard let index = subscriptions.firstIndex(where: { $0.id == id }),
              !refreshing.contains(id) else { return }
        refreshing.insert(id)
        defer { refreshing.remove(id) }

        do {
            let sub = subscriptions[index]
            guard let url = URL(string: sub.url) else { throw SubscriptionError.badURL }
            let parsed = try await fetchServers(from: url)
            guard !parsed.isEmpty else { throw SubscriptionError.empty }

            var identity = sub.deviceID
            if identity == nil || identity!.isEmpty {
                identity = self.identity(in: profiles(from: parsed, subscription: id, identity: nil,
                                                      connections: sub.numConnections))
                    ?? UUID().uuidString
                subscriptions[index].deviceID = identity
            }
            let final = profiles(from: parsed, subscription: id, identity: identity,
                                 connections: sub.numConnections)
            _ = ServerStore.shared.replaceSubscriptionServers(id, with: final)
            subscriptions[index].lastUpdated = Date()
            subscriptions[index].lastError = nil
            save()
            SharedLogger.shared.log("[AppDebug] subscription refreshed: \(sub.hostLabel), "
                + "\(final.count) server(s), one device \(sub.shortIdentity)")
        } catch {
            subscriptions[index].lastError = error.localizedDescription
            save()
            SharedLogger.shared.log("[AppDebug] subscription \(id.uuidString.prefix(8)) failed: "
                + "\(error.localizedDescription)")
        }
    }

    func refreshAll(force: Bool = false) async {
        for sub in subscriptions where sub.enabled {
            if !force, let last = sub.lastUpdated,
               Date().timeIntervalSince(last) < 6 * 60 * 60 { continue }
            await refresh(sub.id)
        }
    }

    /// Called from the server menu on open: a user who just added or changed a
    /// server on the panel expects to see it without a relaunch.
    func refreshIfStale(maxAge: TimeInterval = 15 * 60) async {
        for sub in subscriptions where sub.enabled {
            if let last = sub.lastUpdated, Date().timeIntervalSince(last) < maxAge { continue }
            await refresh(sub.id)
        }
    }

    func resetDevice(_ id: UUID) {
        guard let index = subscriptions.firstIndex(where: { $0.id == id }) else { return }
        let fresh = UUID().uuidString
        subscriptions[index].deviceID = fresh
        // Stamp the new identity onto the profiles this subscription already
        // owns, so the next connect is already the new device. The provider
        // will bind the password/peer to it on the next GETCONF.
        for var profile in ServerStore.shared.servers(for: id) {
            profile.deviceID = fresh
            profile.csqttDeviceID = fresh
            ServerStore.shared.update(profile)
        }
        save()
        SharedLogger.shared.log("[AppDebug] subscription device reset: \(subscriptions[index].hostLabel) → "
            + "\(String(fresh.prefix(8)))")
    }

    // MARK: - Profile construction

    private func profiles(from servers: [SubscriptionServer],
                          subscription id: UUID,
                          identity: String?,
                          connections: Int? = nil) -> [ServerProfile] {
        var out: [ServerProfile] = []
        for server in servers {
            guard let link = try? BackupManager.parseConnectionLinkString(server.link) else {
                SharedLogger.shared.log("[AppDebug] subscription: skipped an unparseable link (\(server.name))")
                continue
            }
            var profile = ServerProfile(link: link.settings)
            if !server.name.isEmpty { profile.serverName = server.name }
            if profile.serverName.isEmpty { profile.serverName = "Server" }
            profile.subscriptionId = id
            profile.remoteKey = server.remoteKey
            // The subscription's own "conn" overrides whatever the link or the
            // profile default said. A link carries no connections today, but
            // the override is applied AFTER ServerProfile(link:) on purpose:
            // the number belongs to the subscription, and a future link field
            // must not quietly win over the value the user chose here.
            if let connections, connections > 0 {
                profile.numConnections = min(max(connections, 1), TunnelConfig.anonConnCap)
            }
            if let identity, !identity.isEmpty {
                profile.deviceID = identity
                profile.csqttDeviceID = identity
            }
            out.append(profile)
        }
        return out
    }

    /// Set (or clear, with nil) the "conn" applied to every server of a
    /// subscription. The change lands on the profiles the subscription already
    /// owns, so the user sees it at once instead of waiting for the next
    /// refresh — and it survives the refresh because the value lives on the
    /// subscription, not on the profiles.
    ///
    /// Clearing to "Auto" deliberately does NOT rewrite the profiles: their
    /// current value is the only remaining record of what they had, and
    /// picking a number here is a deliberate act, not a default worth losing.
    /// The next refresh then re-reads each server's own value.
    func setNumConnections(_ id: UUID, _ value: Int?) {
        guard let index = subscriptions.firstIndex(where: { $0.id == id }) else { return }
        let clamped = value.map { min(max($0, 1), TunnelConfig.anonConnCap) }
        subscriptions[index].numConnections = clamped
        for var profile in ServerStore.shared.servers(for: id) {
            if let clamped { profile.numConnections = clamped }
            ServerStore.shared.update(profile)
        }
        save()
        SharedLogger.shared.log("[AppDebug] subscription conn: \(subscriptions[index].hostLabel) → "
            + (clamped.map(String.init) ?? "auto")
            + " for \(ServerStore.shared.servers(for: id).count) server(s)")
    }

    private func identity(in profiles: [ServerProfile]) -> String? {
        for profile in profiles {
            if !profile.csqttDeviceID.isEmpty { return profile.csqttDeviceID }
            if !profile.deviceID.isEmpty { return profile.deviceID }
        }
        return nil
    }

    private func ensureDeviceIdentities() {
        var changed = false
        for index in subscriptions.indices {
            if subscriptions[index].deviceID?.isEmpty != false {
                subscriptions[index].deviceID = UUID().uuidString
                changed = true
            }
        }
        if changed { save() }
    }

    // MARK: - Networking

    private func fetchServers(from url: URL) async throws -> [SubscriptionServer] {
        var request = URLRequest(url: url)
        request.timeoutInterval = 15
        request.setValue("application/json, text/html;q=0.9, */*", forHTTPHeaderField: "Accept")
        let (data, response) = try await URLSession.shared.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw SubscriptionError.malformed("no HTTP response")
        }
        guard (200..<300).contains(http.statusCode) else {
            throw SubscriptionError.http(http.statusCode)
        }
        let servers = try SubscriptionParser.parse(
            data: data,
            contentType: http.value(forHTTPHeaderField: "Content-Type"),
            baseURL: url)
        return servers
    }

    private func isLocal(_ url: URL) -> Bool {
        guard let host = url.host?.lowercased() else { return false }
        return host == "localhost" || host == "127.0.0.1" || host == "::1"
    }

    // MARK: - Persistence

    private func load() {
        guard let data = d.data(forKey: key),
              let decoded = try? JSONDecoder().decode([Subscription].self, from: data)
        else { return }
        subscriptions = decoded
    }

    private func save() {
        if let data = try? JSONEncoder().encode(subscriptions) {
            d.set(data, forKey: key)
        }
    }
}
